-- PKG_SYS0014 — 적용 후 확인 (SCM_MGR · 조회 전용)
SET PAGESIZE 200 LINESIZE 300

SELECT 'PKG_SYS0014' OBJ, 'PACKAGE' TYP, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_SYS0014' AND OBJECT_TYPE = 'PACKAGE') STATUS, CASE WHEN (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) FROM USER_SOURCE WHERE NAME = 'PKG_SYS0014' AND TYPE = 'PACKAGE' AND LINE > 1) = 49486090810 THEN 'SAME(사내 적용본)' ELSE 'CHECK' END SOURCE_CHK FROM DUAL;
SELECT 'PKG_SYS0014' OBJ, 'PACKAGE BODY' TYP, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_SYS0014' AND OBJECT_TYPE = 'PACKAGE BODY') STATUS, CASE WHEN (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) FROM USER_SOURCE WHERE NAME = 'PKG_SYS0014' AND TYPE = 'PACKAGE BODY' AND LINE > 1) = 716622798671 THEN 'SAME(사내 적용본)' ELSE 'CHECK' END SOURCE_CHK FROM DUAL;
SELECT NAME, TYPE, LINE, POSITION, TEXT FROM USER_ERRORS WHERE NAME IN ('PKG_SYS0014') ORDER BY NAME, TYPE, SEQUENCE;
SELECT OBJECT_NAME PKG, PROCEDURE_NAME MEMBER FROM USER_PROCEDURES WHERE OBJECT_NAME = 'PKG_SYS0014' AND PROCEDURE_NAME IN ('P_SYS0014_GET_AUTH_LIST_M', 'P_SYS0014_GET_GROUP_LIST_M', 'P_SYS0014_GET_USER_BY_GROUP_M', 'P_SYS0014_SAVE_GROUP_USER_M') ORDER BY 2;  -- 기대 4행
SELECT OBJECT_NAME, OBJECT_TYPE FROM USER_OBJECTS WHERE STATUS = 'INVALID' AND OBJECT_TYPE IN ('PACKAGE','PACKAGE BODY','PROCEDURE','FUNCTION') ORDER BY 1;
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM USER_TAB_PRIVS WHERE GRANTEE = 'SCMP_APP' AND TABLE_NAME = 'PKG_SYS0014';
